'use strict';
const $=s=>document.querySelector(s), esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const people=[['И','Ирина','#b6a2f4'],['А','Алексей','#86b9e5'],['М','Мария','#dba994'],['Д','Дмитрий','#9fcdb8']];

const projectStorageKey='vtask-prototype-projects-v1', themeStorageKey='vtask-prototype-theme-v1';
const defaultProjects=[{id:'vtask',title:'VTASK',goal:'Надёжный путь от совещания до выполненного поручения.',owner:'Ирина',stage:'Проверка прототипа',due:'2026-11-04',blocker:'Не согласованы критерии приёмки.'}];
let projects=structuredClone(defaultProjects), theme='system';
try{const stored=JSON.parse(localStorage.getItem(projectStorageKey)||'null');if(Array.isArray(stored)&&stored.every(p=>p&&typeof p.id==='string'&&typeof p.title==='string'&&typeof p.goal==='string'&&typeof p.owner==='string'&&typeof p.stage==='string'&&typeof p.due==='string'&&typeof p.blocker==='string'))projects=stored;const saved=localStorage.getItem(themeStorageKey);if(['light','dark','system'].includes(saved))theme=saved;}catch{}
const themeMedia=matchMedia('(prefers-color-scheme: dark)');
function applyTheme(){document.documentElement.dataset.theme=theme;document.documentElement.dataset.resolvedTheme=theme==='system'?(themeMedia.matches?'dark':'light'):theme;document.querySelectorAll('[data-theme-select]').forEach(el=>el.value=theme);}
themeMedia.addEventListener('change',()=>{if(theme==='system')applyTheme();});
function themeOptions(){return ['system','light','dark'].map((value,i)=>`<option value="${value}" ${theme===value?'selected':''}>${['Как в системе','Светлая','Тёмная'][i]}</option>`).join('');}
function projectScreen(){return heading('Рабочее пространство','Проекты','Цель, ближайший этап и препятствия — в одном месте.','<button class="primary" data-action="new-project">Создать проект</button>')+`<p class="mobile-note">Проекты прототипа сохраняются в этом браузере. С рабочей БД они пока не связаны.</p><div class="project-grid">${projects.map(p=>`<section class="panel project-card"><div class="section-head"><h2>${esc(p.title)}</h2><button class="text-link" data-project="${esc(p.id)}">Изменить</button></div><p>${esc(p.goal||'Цель пока не указана')}</p><dl><dt>Владелец</dt><dd>${esc(p.owner)}</dd><dt>Ближайший этап</dt><dd>${esc(p.stage||'Не указан')}</dd><dt>Срок</dt><dd>${p.due?date(p.due):'Без срока'}</dd></dl>${p.blocker?`<div class="notice">Препятствие: ${esc(p.blocker)}</div>`:''}${p.id==='vtask'?'<div class="row-actions" style="margin-top:20px"><button data-go="tasks">Задачи</button><button data-go="completed">Совещания и решения</button></div>':'<p class="mobile-note">В этом проекте пока нет задач и совещаний.</p>'}</section>`).join('')||'<section class="panel"><p>Создайте первый проект.</p></section>'}</div>`;}
function projectForm(id=null){const p=projects.find(p=>p.id===id)||{title:'',goal:'',owner:'Ирина',stage:'',due:'',blocker:''};openDrawer(id?'Изменить проект':'Новый проект',`<form id="projectForm" data-id="${id?esc(id):''}" class="stack"><label>Название проекта<input name="title" required maxlength="160" value="${esc(p.title)}" autofocus></label><label>Цель<textarea name="goal" maxlength="2000">${esc(p.goal)}</textarea></label><label>Владелец<select name="owner">${people.map(([,name])=>`<option ${p.owner===name?'selected':''}>${name}</option>`).join('')}</select></label><label>Ближайший этап<input name="stage" maxlength="200" value="${esc(p.stage)}"></label><label>Срок<input name="due" type="date" value="${esc(p.due)}"></label><label>Препятствия<textarea name="blocker" maxlength="2000">${esc(p.blocker)}</textarea></label><p class="mobile-note">Сохранится в этом браузере, в данных прототипа.</p><p id="projectError" role="alert" hidden></p><button type="submit" class="primary">${id?'Сохранить изменения':'Создать проект'}</button></form>`);$('#projectForm input').focus();}

const initialTasks=[{id:1,title:'Согласовать сценарий записи встречи',owner:'Ирина',due:'2026-11-02',status:'В работе',source:'s1',blocked:false,revision:1},{id:2,title:'Подготовить список критериев приёмки',owner:'Алексей',due:'2026-11-03',status:'К выполнению',source:'s2',blocked:true,revision:1}];
let tasks=structuredClone(initialTasks), approved=false, paused=false, muted=false, seconds=12*60+34, meetingTab='tasks', route='today', filter='Мои', query='', board=false, transcriptQuery='', sourceId='', notes='', audioPosition=0, activeEnded=false, drawerOpener=null, toastTimer, notices={channel:'Нет',frequency:'Сразу',timezone:'Europe/Moscow',from:'22:00',to:'09:00'};
const history=[{task:1,text:'Ирина · создано вручную из реплики 02:14 · 2 ноября 2026, 10:28 MSK'}];
const clock=s=>`${String(Math.floor(s/60)).padStart(2,'0')}:${String(s%60).padStart(2,'0')}`;
const date=d=>new Intl.DateTimeFormat('ru-RU',{day:'numeric',month:'long',year:'numeric',timeZone:'UTC'}).format(new Date(d+'T12:00:00Z'));
const sourceButton=id=>!id?`<small>Создано вручную</small>`:`<button class="source" data-source="${id}">К исходной реплике · ${id==='s1'?'02:14':'05:38'}</button>`;
function notify(s){$('#toast').textContent=s;$('#toast').hidden=false;clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').hidden=true,4500);}
function taskRow(t){return `<article class="task-row"><div class="task-content"><button class="task-title" data-task="${t.id}">${esc(t.title)}</button><div class="meta"><span>${esc(t.owner)}</span><span>${esc(t.status)}</span>${t.blocked?'<span class="badge amber">Заблокировано</span>':''}</div>${sourceButton(t.source)}</div><span class="due">${date(t.due)}</span></article>`;}
function heading(eyebrow,title,description,action=''){return `<div class="heading"><div><div class="eyebrow">${eyebrow}</div><h1>${title}</h1><p>${description}</p></div>${action}</div>`;}
function today(){return heading('Понедельник, 2 ноября 2026','Сегодня','Всё, что требует вашего внимания.','<button class="primary" data-go="active">Открыть совещание</button>')+`<div class="stats"><div class="stat"><strong>${tasks.filter(t=>t.owner==='Ирина'&&t.status!=='Готово').length}</strong>Мои задачи</div><div class="stat"><strong>1</strong>Совещание сегодня</div><div class="stat"><strong>${approved?0:1}</strong>На подтверждение</div></div><div class="grid"><div><section class="panel"><div class="section-head"><h2>В фокусе</h2><button class="text-link" data-go="tasks">Все задачи</button></div>${tasks.map(taskRow).join('')}<div class="notice">Нужны критерии приёмки<p>Алексей ждёт вашего решения, чтобы завершить подготовку.</p><button class="text-link" data-task="2">Посмотреть блокировку</button></div></section><section class="panel"><div class="section-head"><h2>Из совещаний — в работу</h2><span class="badge">${approved?'Подтверждено':'Нужен ответ'}</span></div><p class="muted">${approved?'Поручение подтверждено и добавлено в задачи.':'Один пример предложения ждёт проверки ответственного и срока.'}</p><button class="text-link" data-go="completed">Открыть итоги встречи</button></section></div><div><section class="panel"><h2>Совещания</h2><button class="meeting-link" data-go="active"><span class="live-tag">${activeEnded?'Завершено':'Демо записи'}</span><strong>Планирование VTASK</strong><small>Продукт · 7 участников · ${clock(seconds)}</small></button><button class="meeting-link" data-go="completed"><strong>Обсуждение сценария встречи</strong><small>Сегодня, 10:00 · Поручения и решения</small></button></section><section class="panel assistant-card"><div class="section-head"><h2>Держать фокус проще</h2><span class="badge">Ассистент</span></div><p>Проверить сроки, разобрать блокировки и уточнить поручения в контексте вашего дня.</p><button data-action="assistant">Открыть диалог</button><p class="mobile-note">Интерфейс диалога готов. Бот и AI не подключены.</p></section></div></div>`;}
function active(){return heading('Совещания / Продукт','Планирование VTASK','2 ноября · 7 участников · локальный режим','<button class="tertiary" data-go="completed">Пример завершённой встречи</button>')+`<div class="grid"><section><div class="circle-stage"><div class="orbit" aria-label="Круг участников. Текущий говорящий неизвестен."><div class="orbit-center"><span class="record-state" id="recordState">${activeEnded?'Завершено':paused?'Пауза':'Запись · демо'}</span><div class="clock" id="clock">${clock(seconds)}</div><small id="speakerState">${activeEnded?'Аудио в этом прототипе не записывается':paused?'Запись приостановлена':'Говорящий определяется'}</small></div>${people.map(([initial,name,color])=>`<div class="participant" style="--speaker:${color}"><span class="avatar">${initial}</span><strong>${name}</strong><small>Участник</small></div>`).join('')}<div class="participant"><button data-action="people" aria-label="Показать ещё 3 участников">Ещё 3</button><strong>Участники</strong></div></div></div><div class="record-controls"><button data-action="pause" ${activeEnded?'disabled':''}>${paused?'Продолжить запись':'Пауза'}</button><button class="primary" data-action="finish" ${activeEnded?'disabled':''}>Завершить совещание</button><button data-action="mic" aria-pressed="${muted}" ${activeEnded?'disabled':''}>${muted?'Включить микрофон':'Микрофон включён'}</button></div><p class="mobile-note">Демонстрация управления. Реальный микрофон не включается.</p></section><section class="panel live-panel"><div class="section-head"><h2>Текущая реплика</h2><span class="badge">Предварительно</span></div><div class="speaker-line"><span>Неизвестный говорящий</span><span>12:22</span></div><p class="utterance">«Давайте сначала проверим полный путь: записали встречу, разобрали поручения и подтвердили задачи».</p><p class="muted" style="font-size:12px">Пример предварительного текста. Имя и разделение говорящих появятся после обработки.</p><button class="text-link" data-action="live-transcript">Открыть полный транскрипт</button><footer>Цвета участников закреплены. Подсветка конкретного человека появится только при наличии событий определения говорящего. Общий уровень микрофона для этого не используется.</footer><details><summary>Микрофон и обработка</summary><label>Источник<select><option>Микрофон Mac — пример</option></select></label><p class="mobile-note">Изменения источника недоступны в прототипе. Live-текст предварительный, полная обработка выполняется после встречи.</p></details></section></div>`;}
function proposal(){return `<div class="proposal"><span class="badge">Пример предложения · требует проверки</span><article class="task-row"><div class="task-content"><h3>Проверить новый интерфейс на мобильном</h3><div class="meta"><span>Ирина</span><span>4 ноября 2026</span></div>${sourceButton('s2')}</div></article><p>Пока не задача. После подтверждения появится в общем списке.</p><button class="primary" data-action="approve">Проверить и подтвердить</button></div>`;}
const segments=[{id:'s1',time:'02:14',name:'Ирина',color:people[0][2],text:'Я согласую сценарий записи встречи сегодня. Сохраним паузу и возможность продолжить встречу.'},{id:'s2',time:'05:38',name:'Алексей',color:people[1][2],text:'Подготовлю критерии приёмки к третьему ноября. Ещё предлагаю Ирине проверить интерфейс на мобильном к четвёртому ноября.'},{id:'s3',time:'08:12',name:'Неизвестный говорящий',color:'#b0bdd0',text:'По сводке решения пока запишем вручную, автоматического резюме у нас ещё нет.'}];
const pristineSegments=structuredClone(segments);
function transcript(){const rows=segments.filter(s=>(s.name+' '+s.text).toLowerCase().includes(transcriptQuery.toLowerCase()));return `<div class="transcript-toolbar"><label style="flex:1">Поиск по транскрипту<input id="transcriptSearch" type="search" value="${esc(transcriptQuery)}" placeholder="Текст или говорящий"></label><span class="badge">Имена подтверждены вручную · демо</span></div><div id="segments">${rows.length?rows.map(s=>`<article id="${s.id}" class="transcript-segment ${sourceId===s.id?'highlight':''}" style="--speaker:${s.color}"><div class="speaker-line"><span class="speaker-chip">${s.name}</span><button class="source" data-seek="${s.time}">${s.time}</button></div><p>${esc(s.text)}</p><button class="text-link" data-edit="${s.id}">Исправить текст</button></article>`).join(''):'<p class="empty">Совпадений нет.</p>'}</div>`;}
function completed(){return heading('Совещания / Продукт','Обсуждение сценария встречи','2 ноября, 10:00 · 18 минут · завершено','<div class="row-actions"><button data-action="continue">Продолжить встречу</button><button class="tertiary" data-action="more">Дополнительно</button></div>')+`<div class="audio"><button data-action="audio">Аудио · демо</button><span id="audioTime">${clock(audioPosition)}</span><input id="audioRange" aria-label="Позиция записи (демо)" type="range" min="0" max="1080" value="${audioPosition}"><span>18:00</span><small>Файл не подключён</small></div><div class="tabs" role="tablist" aria-label="Результаты совещания">${[['summary','Итоги'],['transcript','Транскрипт'],['tasks','Задачи']].map(([id,name])=>`<button role="tab" id="tab-${id}" aria-controls="meetingContent" data-tab="${id}" tabindex="${meetingTab===id?0:-1}" aria-selected="${meetingTab===id}">${name}${id==='tasks'?' · '+tasks.length:''}</button>`).join('')}</div><div id="meetingContent" role="tabpanel" aria-labelledby="tab-${meetingTab}">${meetingTab==='transcript'?transcript():meetingTab==='summary'?`<div class="grid"><section class="panel"><div class="section-head"><h2>Ручные итоги</h2><button class="text-link" data-action="notes">${notes?'Изменить':'Добавить заметку'}</button></div>${notes?`<p class="summary-note">${esc(notes)}</p>`:'<p class="empty">Итоги ещё не добавлены. Автоматическое резюме не подключено.</p>'}<h3>Решение · пример</h3><p class="muted">Сначала проверяем кликабельный прототип, затем переносим интерфейс в рабочую панель.</p>${sourceButton('s1')}</section><section class="panel"><h2>Открытые вопросы</h2><p class="muted">Какие критерии использовать для аппаратной приёмки?</p><button class="text-link" data-action="assistant">Обсудить с ассистентом</button></section></div>`:`<div class="grid"><section class="panel"><div class="section-head"><h2>Подтверждённые поручения</h2><span class="badge green">${tasks.length} задачи</span></div>${tasks.map(taskRow).join('')}${!approved?proposal():''}</section><section class="panel"><h2>Следующий шаг</h2><p class="muted">Проверьте формулировку, ответственного и итоговую дату каждого предложения.</p><p class="muted" style="font-size:12px">Созданные задачи связаны с исходной репликой. Автор, источник и время доступны в истории карточки.</p><button class="text-link" data-go="today">Вернуться к сегодняшнему дню</button></section></div>`}</div>`;}
function taskScreen(){let visible=tasks.filter(t=>(!query||t.title.toLowerCase().includes(query.toLowerCase()))&&(filter!=='Мои'||t.owner==='Ирина')&&(filter!=='Сегодня'||t.due==='2026-11-02')&&(filter!=='Просрочены'||t.due<'2026-11-02')&&(filter!=='Заблокированы'||t.blocked));return heading('Рабочее пространство','Задачи','От подтверждённого поручения — к выполнению.','<button class="primary" data-action="new-task">Создать задачу</button>')+`<div class="row-actions" style="margin-bottom:22px"><label style="flex:1;min-width:150px;max-width:350px">Поиск<input id="taskSearch" type="search" value="${esc(query)}" placeholder="Найти задачу"></label>${['Мои','Сегодня','Просрочены','Все'].map(f=>`<button data-filter="${f}" aria-pressed="${filter===f}" ${filter===f?'class="primary"':''}>${f}</button>`).join('')}<button data-action="filters">Фильтры</button><button data-action="view">${board?'Показать список':'Показать доску'}</button></div>${board?`<div class="board">${['К выполнению','В работе','Готово'].map(s=>`<section class="panel"><h2>${s}</h2>${visible.filter(t=>t.status===s).map(taskRow).join('')||'<p class="muted">Нет задач</p>'}</section>`).join('')}</div>`:`<section class="panel">${visible.map(taskRow).join('')||'<p class="empty">По выбранным условиям задач нет.</p>'}</section>`}`;}
function render(focus=false){route=location.hash.slice(1)||'today';if(!['today','active','completed','tasks','projects','approvals'].includes(route))route='today';$('#crumb').textContent=({today:'Сегодня',active:'Совещания',completed:'Совещания',tasks:'Задачи',projects:'Проекты',approvals:'На подтверждение'})[route];document.querySelectorAll('[data-route]').forEach(a=>{const selected=a.dataset.route===(route==='completed'?'active':route);a.classList.toggle('active',selected);if(selected)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current');});$('#approvalCount').textContent=approved?'0':'1';$('#main').innerHTML=route==='today'?today():route==='active'?active():route==='completed'?completed():route==='tasks'?taskScreen():route==='approvals'?heading('Рабочее пространство','На подтверждение','Предложения появятся в задачах только после проверки.')+(approved?'<section class="panel"><p>Все предложения разобраны.</p><button data-go="tasks">К задачам</button></section>':proposal()):projectScreen();if(focus)$('#main').focus({preventScroll:true});}
function go(id){if(location.hash==='#'+id)render(true);else location.hash=id;}
function openDrawer(title,content){if(!$('#drawer').open)drawerOpener=document.activeElement;$('#drawer').innerHTML=`<div class="drawer-head"><div><h2 id="drawerTitle">${title}</h2><small>Демонстрационный режим</small></div><button data-action="close">Закрыть</button></div>${content}`;if(!$('#drawer').open)$('#drawer').showModal();else $('#drawer button')?.focus();}
$('#drawer').addEventListener('close',()=>{if(drawerOpener?.isConnected)drawerOpener.focus();});
function close(){ if($('#drawer').open)$('#drawer').close(); }
function taskDrawer(id){const t=tasks.find(t=>t.id===id);if(!t)return;openDrawer('Карточка задачи',`<form id="taskForm" class="stack" data-id="${t.id}" data-revision="${t.revision}"><label>Название<input name="title" required value="${esc(t.title)}"></label><label>Статус<select name="status">${['К выполнению','В работе','Готово'].map(s=>`<option ${t.status===s?'selected':''}>${s}</option>`).join('')}</select></label><label>Ответственный<select name="owner">${['Ирина','Алексей','Мария','Дмитрий'].map(n=>`<option ${t.owner===n?'selected':''}>${n}</option>`).join('')}</select></label><label>Итоговая дата<input name="due" type="date" required value="${t.due}"></label><p class="muted">Проект: VTASK${t.blocked?'<br>Блокировка: ожидаются критерии приёмки.':''}</p><section><h3>Источник</h3>${sourceButton(t.source)}<p class="muted" style="font-size:12px">Напоминания не отправляются: канал не подключён.</p></section><button class="primary" type="submit">Проверить изменения</button><section><h3>История</h3>${history.filter(h=>h.task===id).map(h=>`<p class="history">${esc(h.text)}</p>`).join('')||'<p class="history">Алексей · создано из встречи · 2 ноября 2026, 10:28 MSK</p>'}</section></form>`);}
function assistant(){openDrawer('Ассистент',`<div class="context">Контекст: ${esc($('#crumb').textContent)}${route==='active'?' · Планирование VTASK':route==='completed'?' · Обсуждение сценария встречи':''}</div><span class="badge amber">Бот и AI не подключены</span><div class="message" style="margin-top:20px"><p>Здесь можно будет получать сводки и менять задачи с проверкой прав. Сейчас доступны только демонстрационные действия.</p></div><div class="stack"><button data-go="tasks">Посмотреть задачи</button><button data-task="1">Пример изменения срока</button><button data-go="approvals">Разобрать предложения</button><button data-action="settings">Канал и тихие часы</button></div><label style="margin-top:24px">Сообщение<textarea disabled placeholder="Отправка появится после подключения сервиса"></textarea></label><button disabled style="margin-top:12px">Отправить</button>`);}
function settings(){openDrawer('Настройки',`<label>Тема интерфейса<select data-theme-select>${themeOptions()}</select></label><p class="mobile-note">Тема сохраняется в этом браузере. Системная следует оформлению macOS.</p><h3 style="margin-top:28px">Уведомления</h3><p class="muted">Настройки уведомлений сохраняются только до перезагрузки прототипа. Доставка не подключена.</p><form id="settingsForm" class="stack"><label>Канал<select name="channel"><option>Нет</option><option ${notices.channel==='Бот'?'selected':''}>Бот</option><option ${notices.channel==='Веб-панель'?'selected':''}>Веб-панель</option></select></label><label>Частота<select name="frequency"><option>Сразу</option><option ${notices.frequency==='Ежедневная сводка'?'selected':''}>Ежедневная сводка</option></select></label><label>Часовой пояс<select name="timezone"><option>Europe/Moscow</option><option ${notices.timezone==='Asia/Yekaterinburg'?'selected':''}>Asia/Yekaterinburg</option></select></label><label>Тихие часы: с<input name="from" type="time" value="${notices.from}" required></label><label>До<input name="to" type="time" value="${notices.to}" required></label><button class="primary">Сохранить пример</button><div class="notice">Статус доставки: не подключено<p>Проверка отправки и реальные уведомления недоступны.</p></div></form>`);}
function approve(){openDrawer('Подтвердить поручение',`<form id="approveForm" class="stack"><label>Поручение<input name="title" value="Проверить новый интерфейс на мобильном" required></label><label>Ответственный<select name="owner"><option>Ирина</option><option>Алексей</option></select></label><label>Итоговая дата<input name="due" type="date" value="2026-11-04" required></label>${sourceButton('s2')}<p class="muted">Создаст одну задачу в демо. История сохранит автора, время и источник.</p><button class="primary">Подтвердить и создать задачу</button></form>`);}
document.addEventListener('click',event=>{const b=event.target.closest('button');if(!b)return;if(Object.keys(b.dataset).length)event.preventDefault();if(b.dataset.project){projectForm(b.dataset.project);return;}if(b.dataset.go){close();go(b.dataset.go);return;}if(b.dataset.task){taskDrawer(Number(b.dataset.task));return;}if(b.dataset.source){sourceId=b.dataset.source;meetingTab='transcript';transcriptQuery='';close();go('completed');requestAnimationFrame(()=>{const target=$('#'+sourceId);if(target){target.tabIndex=-1;target.focus();target.scrollIntoView({block:'center'});}});return;}if(b.dataset.tab){meetingTab=b.dataset.tab;render();$('#tab-'+meetingTab)?.focus();return;}if(b.dataset.filter){filter=b.dataset.filter;render();return;}if(b.dataset.seek){const [m,s]=b.dataset.seek.split(':').map(Number);audioPosition=m*60+s;$('#audioTime').textContent=clock(audioPosition);$('#audioRange').value=audioPosition;notify('Позиция примера: '+b.dataset.seek+'. Аудиофайл не подключён.');return;}if(b.dataset.edit){const s=segments.find(s=>s.id===b.dataset.edit);openDrawer('Исправить реплику',`<form id="editForm" class="stack" data-id="${s.id}"><label>Текст<textarea name="text" required>${esc(s.text)}</textarea></label><button class="primary">Сохранить в демо</button></form>`);return;}if(b.dataset.info){openDrawer(b.dataset.info,`<p class="muted">Этот раздел остаётся в рабочем приложении. Его обновление входит в следующий этап после согласования трёх основных экранов.</p>`);return;}switch(b.dataset.action){case 'new-project':projectForm();break;case 'assistant':assistant();break;case 'close':close();break;case 'settings':settings();break;case 'pause':paused=!paused;render();document.querySelector('[data-action=pause]').focus();break;case 'mic':muted=!muted;render();document.querySelector('[data-action=mic]').focus();notify('Состояние микрофона изменено только в демо.');break;case 'finish':openDrawer('Завершить совещание?',`<p>В рабочем приложении аудио будет сохранено и отправлено на обработку. В этом прототипе откроется пример результата.</p><button class="primary" data-action="finish-confirm">Завершить и посмотреть результат</button>`);break;case 'finish-confirm':activeEnded=true;close();meetingTab='tasks';go('completed');notify('Открыт демонстрационный результат. Модель не запускалась.');break;case 'continue':activeEnded=false;paused=false;go('active');notify('Демо продолжения той же встречи. Реальная запись не запускается.');break;case 'people':openDrawer('Участники встречи',`<p>Ирина, Алексей, Мария, Дмитрий, Анна, Олег, Сергей.</p><p class="muted">Список участников не является результатом идентификации голоса.</p>`);break;case 'live-transcript':openDrawer('Предварительный транскрипт','<span class="badge">Демонстрационный текст</span><p class="muted" style="margin-top:20px">12:22 · Неизвестный говорящий</p><p>Давайте сначала проверим полный путь: записали встречу, разобрали поручения и подтвердили задачи.</p><p class="muted">Полная версия появится после завершения обработки.</p>');break;case 'approve':if(!approved)approve();break;case 'notes':openDrawer('Ручные итоги',`<form id="notesForm" class="stack"><label>Заметка<textarea name="notes" required>${esc(notes)}</textarea></label><button class="primary">Сохранить заметку</button></form>`);break;case 'more':openDrawer('Дополнительные действия','<p class="muted">Импорт, повторная обработка и экспорт сохранятся в рабочей панели. В прототипе обработка аудио не запускается.</p><button data-action="continue">Продолжить встречу</button>');break;case 'audio':notify('Демонстрационный плеер: аудиофайл не подключён. Таймкоды меняют позицию примера.');break;case 'view':board=!board;render();break;case 'filters':openDrawer('Фильтры','<p class="muted">Дополнительная выборка для проверки блокировок.</p><button data-action="blocked">Только заблокированные</button>');break;case 'blocked':filter='Заблокированы';close();render();break;case 'new-task':openDrawer('Новая задача',`<form id="newTaskForm" class="stack"><label>Название<input name="title" required></label><label>Итоговая дата<input name="due" type="date" required value="2026-11-04"></label><p class="muted">Ответственный: Ирина · Проект: VTASK · Источник: вручную</p><button class="primary">Создать в демо</button></form>`);break;case 'apply':{const f=$('#previewForm'),id=Number(f.dataset.id),t=tasks.find(t=>t.id===id);if(!t||t.revision!==Number(f.dataset.revision)){notify('Задача изменилась. Откройте карточку заново.');close();return;}const data=JSON.parse(f.dataset.changes);Object.assign(t,data);t.revision++;history.push({task:id,text:`Ирина · веб-панель (демо) · ${new Date().toLocaleString('ru-RU',{timeZone:'Europe/Moscow'})} MSK · дата ${date(t.due)}, ${t.status}, ${t.owner}`});close();render();notify('Изменения применены в демо. История обновлена.');break;}case 'reset':tasks=structuredClone(initialTasks);approved=false;paused=false;muted=false;activeEnded=false;seconds=754;notes='';filter='Мои';query='';board=false;transcriptQuery='';sourceId='';history.splice(1);segments.splice(0,segments.length,...structuredClone(pristineSegments));notices={channel:'Нет',frequency:'Сразу',timezone:'Europe/Moscow',from:'22:00',to:'09:00'};close();go('today');render();notify('Примеры сброшены. Ваши проекты и выбор темы сохранены.');break;}});
document.addEventListener('input',event=>{if(event.target.id==='audioRange'){audioPosition=Number(event.target.value);$('#audioTime').textContent=clock(audioPosition);}if(['taskSearch','transcriptSearch'].includes(event.target.id)){const el=event.target,id=el.id,pos=el.selectionStart;if(id==='taskSearch')query=el.value;else transcriptQuery=el.value;render();const replacement=$('#'+id);replacement.focus();replacement.setSelectionRange(pos,pos);}});
document.addEventListener('keydown',e=>{if(e.target.matches('[role=tab]')&&['ArrowLeft','ArrowRight','Home','End'].includes(e.key)){e.preventDefault();const tabs=['summary','transcript','tasks'],index=tabs.indexOf(meetingTab);meetingTab=e.key==='Home'?tabs[0]:e.key==='End'?tabs[2]:tabs[(index+(e.key==='ArrowRight'?1:2))%3];render();$('#tab-'+meetingTab).focus();}});
document.addEventListener('submit',event=>{event.preventDefault();const f=event.target,v=Object.fromEntries(new FormData(f));if(f.id==='projectForm'){v.title=v.title.trim();if(!v.title){$('#projectError').textContent='Введите название проекта.';$('#projectError').hidden=false;f.elements.title.focus();return;}const id=f.dataset.id||crypto.randomUUID(),project={id,...v},next=f.dataset.id?projects.map(p=>p.id===id?project:p):[...projects,project];try{localStorage.setItem(projectStorageKey,JSON.stringify(next));}catch{$('#projectError').textContent='Браузер не разрешил сохранить проект. Проверьте доступ к локальному хранилищу.';$('#projectError').hidden=false;return;}projects=next;close();go('projects');render();notify(f.dataset.id?'Проект обновлён в прототипе.':'Проект создан и сохранён в этом браузере.');}else if(f.id==='approveForm'){if(approved)return;approved=true;const id=Math.max(...tasks.map(t=>t.id))+1;tasks.push({id,...v,status:'К выполнению',source:'s2',blocked:false,revision:1});history.push({task:id,text:`Ирина · подтверждено предложение из встречи, реплика 05:38 · ${new Date().toLocaleString('ru-RU',{timeZone:'Europe/Moscow'})} MSK`});close();render();notify('Поручение подтверждено. Создана одна задача в демо.');}else if(f.id==='taskForm'){const t=tasks.find(t=>t.id===Number(f.dataset.id));const consequences=t.id===1&&v.due!==t.due?'Перенос не снимает блокировку задачи «Подготовить список критериев приёмки». Её срок остаётся 3 ноября 2026. Зависимые сроки не меняются автоматически.':'Зависимые задачи не изменяются.';openDrawer('Проверить изменения',`<form id="previewForm" data-id="${t.id}" data-revision="${f.dataset.revision}" data-changes="${esc(JSON.stringify(v))}"><p>${esc(v.title)}</p><p>Итоговая дата: <strong>${date(v.due)}</strong></p><p>Ответственный: ${esc(v.owner)}<br>Статус: ${esc(v.status)}</p><div class="notice">${consequences}</div><p class="muted" style="margin-top:20px">Изменение от имени Ирины · веб-панель · версия ${t.revision}</p><button class="primary" type="button" data-action="apply">Подтвердить изменения</button></form>`);}else if(f.id==='notesForm'){notes=v.notes;close();render();notify('Ручные итоги сохранены в демо.');}else if(f.id==='settingsForm'){notices=v;close();notify('Настройки примера сохранены. Уведомления не отправляются.');}else if(f.id==='editForm'){segments.find(s=>s.id===f.dataset.id).text=v.text;close();render();notify('Текст исправлен в прототипе.');}else if(f.id==='newTaskForm'){const id=Math.max(...tasks.map(t=>t.id))+1;tasks.push({id,...v,owner:'Ирина',status:'К выполнению',source:'',blocked:false,revision:1});history.push({task:id,text:`Ирина · создано вручную · ${new Date().toLocaleString('ru-RU',{timeZone:'Europe/Moscow'})} MSK`});close();render();notify('Задача создана в демо.');}});
document.addEventListener('change',event=>{if(event.target.matches('[data-theme-select]')){theme=event.target.value;applyTheme();try{localStorage.setItem(themeStorageKey,theme);}catch{notify('Тема применена, но браузер не разрешил запомнить выбор.');}}});
applyTheme();
window.addEventListener('hashchange',()=>{render(true);window.scrollTo(0,0);});setInterval(()=>{if(route==='active'&&!paused&&!activeEnded){seconds++;if($('#clock'))$('#clock').textContent=clock(seconds);}},1000);render();
